from typing import Protocol
from dataclasses import dataclass

@dataclass
class ChatResponse:
    content: str
    tool_calls: list[dict] | None = None

class InferenceEngine(Protocol):
    def chat(self, messages: list[dict], tools: list[dict] | None = None, **kw) -> ChatResponse: ...

class OfflineStub:
