from openai import OpenAI

class OllamaAdapter:
    def __init__(self, model='qwen3:8b', port=11434):
        self.client = OpenAI(base_url=f'http://localhost:{port}/v1', api_key='ollama')
        self.model = model
    def chat(self, messages, tools=None, **kw):
        resp = self.client.chat.completions.create(
            model=self.model, messages=messages,
            tools=tools, temperature=0, **kw)
        m = resp.choices[0].message
        return ChatResponse(content=m.content or '', tool_calls=[tc.model_dump() for tc in (m.tool_calls or [])])

def operator_loop(engine: InferenceEngine, state: dict, tools: list[dict], max_rounds=12):
    history = [{'role': 'user', 'content': build_prompt(state)}]
    for _ in range(max_rounds):
        resp = engine.chat(history, tools=tools)
        history.append({'role': 'assistant', 'content': resp.content})
        if resp.tool_calls:
            for tc in resp.tool_calls:
                result = dispatch_tool(tc)   # numpy/MLX executes here
                history.append({'role': 'tool', 'content': result})
        else:
            return parse_terminal(resp.content)  # structured JSON output
    raise RuntimeError('operator loop did not converge')
